LAW_TAGS = {}
for t in TOPICS:
    for j, v in enumerate(t["v"]):
        tg = v.pop("tag", None)
        if tg is not None and tg[1] != 0:
            LAW_TAGS.setdefault(t["id"], {})[j] = [tg[0], tg[1]]
        if "a" in v:
            v["a"].pop("other_rev_gdp", None)
            v["a"].pop("infl_shift", None)
            if "unemp_shift" in v["a"]:
                v["a"]["unemp_base"] = v["a"].pop("unemp_shift")
            if not v["a"]:
                v.pop("a")
        if "x" in v and not v["x"]:
            v.pop("x")
